public class DOMNodePointer_findEnclosingAttribute_TriageGen1Test {

    /**
     * Helper method to access the protected static method via reflection.
     */
    @SuppressWarnings("unchecked")
    private String invokeFindEnclosingAttribute(Node n, String attrName) throws Exception {
        Method method = DOMNodePointer.class.getDeclaredMethod("findEnclosingAttribute", Node.class, String.class);
        method.setAccessible(true);
        return (String) method.invoke(null, n, attrName);
    }

    @Test
    public void testFindEnclosingAttribute_NullNode() throws Exception {
        assertNull(invokeFindEnclosingAttribute(null, "testAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_NodeIsNotElementAndNoParent() throws Exception {
        Node textNode = mock(Node.class);
        when(textNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(textNode.getParentNode()).thenReturn(null);

        assertNull(invokeFindEnclosingAttribute(textNode, "testAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_ElementWithAttributeFound() throws Exception {
        Element root = mock(Element.class);
        Element child = mock(Element.class);

        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getParentNode()).thenReturn(root);
        when(root.getNodeType()).thenReturn(Node.ELEMENT_NODE);

        // Target attribute on child
        when(child.getAttribute("myAttr")).thenReturn("targetValue");

        assertEquals("targetValue", invokeFindEnclosingAttribute(child, "myAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_ElementWithEmptyAttributeGoesToParent() throws Exception {
        Element root = mock(Element.class);
        Element child = mock(Element.class);
        Element grandChild = mock(Element.class);

        when(grandChild.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(grandChild.getParentNode()).thenReturn(child);

        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getParentNode()).thenReturn(root);

        when(root.getNodeType()).thenReturn(Node.ELEMENT_NODE);

        // Grandchild has empty attr
        when(grandChild.getAttribute("myAttr")).thenReturn("");
        // Child has null attr (simulating attribute not present)
        when(child.getAttribute("myAttr")).thenReturn(null);
        // Root has the value
        when(root.getAttribute("myAttr")).thenReturn("foundAtRoot");

        assertEquals("foundAtRoot", invokeFindEnclosingAttribute(grandChild, "myAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_NonElementTraversesUp() throws Exception {
        Element root = mock(Element.class);
        Node textNode = mock(Node.class);

        when(textNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(textNode.getParentNode()).thenReturn(root);

        when(root.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(root.getAttribute("myAttr")).thenReturn("rootValue");

        assertEquals("rootValue", invokeFindEnclosingAttribute(textNode, "myAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_TraverseAllTheWayToNull() throws Exception {
        Element root = mock(Element.class);
        when(root.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(root.getAttribute("missing")).thenReturn("");
        when(root.getParentNode()).thenReturn(null);

        assertNull(invokeFindEnclosingAttribute(root, "missing"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeIsNotNullButEmptyString() throws Exception {
        Element root = mock(Element.class);
        when(root.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        // The logic: if (attr != null && !attr.equals(""))
        // We test the branch where it is empty
        when(root.getAttribute("empty")).thenReturn("");
        when(root.getParentNode()).thenReturn(null);

        assertNull(invokeFindEnclosingAttribute(root, "empty"));
    }
}
